css='''@font-face{font-family:Anton;src:url(assets/fonts/anton.woff2)}@font-face{font-family:Inter;src:url(assets/fonts/inter-800.woff2);font-weight:800}@font-face{font-family:Inter;src:url(assets/fonts/inter-500.woff2);font-weight:500}*{box-sizing:border-box;margin:0}html,body{width:1080px;height:1920px;overflow:hidden;background:#080b10}#root{width:1080px;height:1920px;position:relative;color:#f7f7f4;font-family:Inter}.bg{position:absolute;inset:0;width:1080px;height:1920px;object-fit:cover;opacity:0;filter:brightness(.30) saturate(.65)}.bg.palestra{filter:none}#veu{position:absolute;inset:0;background:linear-gradient(180deg,#0009,transparent 30%,transparent 48%,#080b10e0 76%,#080b10)}#logo{position:absolute;right:55px;top:65px;width:125px}.serie{position:absolute;top:85px;left:65px;font-size:24px;letter-spacing:5px;color:#d7ff3a}.scene{position:absolute;inset:0;opacity:0}.inner{position:absolute;left:70px;right:70px;top:300px}h1{font:112px/1.02 Anton;letter-spacing:-1px}h1 em{font-style:normal;color:#d7ff3a}.red{color:#ff5a62}.small{font-size:26px;line-height:1.45;color:#c2c8cf}.label{font-size:25px;letter-spacing:4px;color:#d7ff3a;margin-bottom:24px}.palestra-title{position:absolute;top:230px;left:70px;right:70px;font:100px/1 Anton}.credit{position:absolute;top:1100px;left:70px;right:70px;font-size:27px;line-height:1.5}.credit b{color:#d7ff3a}.card{padding:38px;border:2px solid #ffffff35;border-radius:28px;background:#111b25ed;box-shadow:0 28px 90px #0008;margin-top:35px}.chat{font-size:48px;line-height:1.25}.bubble{border-radius:28px;padding:36px;margin:25px 0;background:#2a3946}.reply{background:#d7ff3a;color:#111;font-weight:800;font-size:65px}.badge{position:absolute;left:70px;top:190px;font-size:23px;letter-spacing:3px;padding:12px 20px;border:1px solid #ffffff60;background:#0007}.row{display:flex;align-items:center;gap:28px;padding:32px 30px;background:#101b24ed;border:1px solid #ffffff40;border-radius:22px;font-size:42px;margin-top:25px}.row b{font:60px Anton;color:#d7ff3a}.row.bad b{color:#ff5a62}.stamp{margin-top:40px;border:5px solid #ff5a62;color:#ff5a62;padding:25px;font:80px/1 Anton;transform:rotate(-4deg)}.note{font-size:32px;color:#c4cbd1;line-height:1.45;margin-top:28px}.cta{margin-top:50px;padding:35px 24px;background:#d7ff3a;border-radius:22px;color:#080b10;font:80px Anton;text-align:center}.sub{position:absolute;top:1450px;left:65px;right:65px;height:230px;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0 18px;opacity:0;text-align:center}.sub span{font:74px/1.12 Anton;text-transform:uppercase;text-shadow:0 5px 20px #000;opacity:.25}.progress{position:absolute;top:0;left:0;width:1080px;height:8px;background:#d7ff3a;transform-origin:left}'''
