script='''const tl=gsap.timeline({paused:true});window.__timelines=window.__timelines||{};
const S=DATA.starts,E=DATA.ends,W=DATA.words,T=DATA.total;
S.forEach((s,i)=>{tl.set('#bg'+i,{opacity:1},s);tl.set('#bg'+i,{opacity:0},E[i]);tl.set('#s'+i,{opacity:1},s);tl.set('#s'+i,{opacity:0},E[i]);if(i>2)tl.fromTo('#s'+i+' .inner',{y:40},{y:0,duration:.35,ease:'power3.out'},s);tl.fromTo('#bg'+i,{scale:1},{scale:1.045,duration:E[i]-s,ease:'none'},s);});
function word(w,start){const p=W.find(x=>x.s>=start-.01&&x.w.toLowerCase().replace(/[.,?!:]/g,'')===w);return p?p.s:start;}
[['inventada','inventar',4],['custo','custo',7],['frete','frete',7],['margem','margem',7],['passo1','interpreta',9],['passo2','sistema',9],['passo3','ferramenta',9]].forEach(([id,w,i])=>{tl.set('#'+id,{opacity:0},0);tl.fromTo('#'+id,{opacity:0,y:25},{opacity:1,y:0,duration:.23},word(w,S[i]));});
let groups=[],g=[];W.forEach((w,i)=>{if(g.length&&(g.length>=4||S.some(s=>s>g[0].s&&s<=w.s))) {groups.push(g);g=[];}g.push(w);if(/[.?!]$/.test(w.w)){groups.push(g);g=[];}});if(g.length)groups.push(g);
groups.forEach((group,i)=>{const d=document.createElement('div');d.className='sub';d.id='sub'+i;group.forEach((w,j)=>{const x=document.createElement('span');x.textContent=w.w;x.id='w'+i+'_'+j;d.appendChild(x);tl.set(x,{opacity:1,color:/invent|err|antigo|fora/i.test(w.w)?'#ff5a62':(/dados|conta|aprova|diagnóstico|precisão/i.test(w.w)?'#d7ff3a':'#ffffff')},w.s);});document.getElementById('palco').appendChild(d);tl.set(d,{opacity:1},group[0].s);tl.set(d,{opacity:0},Math.min(groups[i+1]?.[0].s??T,group.at(-1).e+.22));});
tl.fromTo('.progress',{scaleX:0},{scaleX:1,duration:T,ease:'none'},0);window.__timelines.main=tl;'''
html=f'<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>{css}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="{T}" data-width="1080" data-height="1920">{vid}<div id="veu"></div><div id="palco">{scenes}</div><div class="serie">PROCESSOS & IA</div><img id="logo" src="assets/marca/logo-branca.png"><div class="progress"></div><audio id="narracao" src="assets/audio/master.wav" data-start="0" data-duration="{T-1.2}" data-volume="1"></audio><audio id="trilha" src="assets/audio/trilha.mp3" data-start="{S[3]}" data-duration="{T-S[3]}" data-volume="0.09" data-fade-out="2"></audio></div><script>const DATA={json.dumps(t,ensure_ascii=False)};{script}</script></body></html>'
